  <script>
    document.addEventListener("DOMContentLoaded", () => {
      const TYPES = {
        biologic:   { code: 'BIO',  color: '#ff4fb0' },
        mechanical: { code: 'MECH', color: '#ff9a2e' },
        psychic:    { code: 'PSY',  color: '#19b8f0' },
        quantum:    { code: 'QUA',  color: '#7b5cff' },
        imaginary:  { code: 'IMG',  color: '#d9b24c' },
        typeless:   { code: 'N/A',  color: '#8b9bb5' }
      };

      function hashCode(text) {
        let hash = 0;
        for (let i = 0; i < text.length; i += 1) {
          hash = ((hash << 5) - hash) + text.charCodeAt(i);
          hash |= 0;
        }
        return hash;
      }

      // Retrieve and parse JSON payload
      const rawEl = document.getElementById('__data');
      let rawData = rawEl ? rawEl.value : '';
      rawData = rawData.replace(/<\/?(?:Personnel_Dossier|HI3_Seito)[^>]*>/gi, '').trim();

      let data = {};
      try {
        const decoded = document.createElement('textarea');
        decoded.innerHTML = rawData;
        const clean = (decoded.value || rawData).trim();
        if (clean.startsWith('{')) data = JSON.parse(clean);
      } catch (error) {}

      // Helpers
      const pick = (...keys) => {
        for (const k of keys) {
          const v = data[k];
          if (v === undefined || v === null) continue;
          const s = String(v).trim();
          if (s !== '' && s.toUpperCase() !== 'N/A') return s;
        }
        return '';
      };
      const setText = (id, value, fallback) => {
        const el = document.getElementById(id);
        if (el) el.textContent = value || fallback;
      };
      const setSection = (secId, boxId, value) => {
        const sec = document.getElementById(secId);
        if (!sec) return;
        if (value) {
          sec.style.display = 'block';
          setText(boxId, value, '');
        }
      };

      // Fields (falls back to older key names)
      const name = pick('name');
      const typeRaw = pick('type', 'attribute_type');
      const typeLower = typeRaw.toLowerCase();
      const typeKey = Object.keys(TYPES).find((k) => typeLower.includes(k.slice(0, 3))) || 'typeless';
      const typeInfo = TYPES[typeKey];

      // Theme color from type
      document.documentElement.style.setProperty('--attr-color', typeInfo.color);
      document.documentElement.style.setProperty('--attr-glow', typeInfo.color + '40');

      setText('ui-name', name, 'Unknown');
      setText('ui-callsign', pick('callsign'), 'Registered Personnel');
      setText('ui-id', name ? 'HYP-' + Math.abs(hashCode(name)).toString().padStart(4, '0').slice(0, 4) : '', 'HYP-0000');
      setText('ui-role', pick('role'), 'Unassigned');
      setText('ui-type', typeRaw ? typeRaw.replace(/\s*\(.*\)\s*$/, '') : '', typeKey.charAt(0).toUpperCase() + typeKey.slice(1));
      setText('ui-weapon', pick('weapon', 'combat_style'), 'Unspecified');
      setText('ui-age', pick('age'), 'Unknown');
      setText('ui-gender', pick('gender'), 'Unknown');
      setText('ui-race', pick('race'), 'Unspecified');
      setText('ui-faction', pick('faction'), 'Unaffiliated');
      setText('ui-rank', pick('rank'), '—');
      setText('ui-location', pick('starting_location', 'location'), 'Unknown');
      setText('ui-timeline', pick('timeline', 'starting_scenario'), 'Main Timeline (Canon)');
      setText('ui-appearance', pick('appearance'), 'No physical description recorded.');
      setText('ui-footer-type', typeInfo.code, 'N/A');

      setSection('sec-objective', 'ui-objective', pick('objective'));
      setSection('sec-background', 'ui-background', pick('background'));
      setSection('sec-scenario', 'ui-scenario', pick('scenario', 'custom_starting_scenario'));

      // Relationships (list of { name, relation, note })
      const relBox = document.getElementById('ui-relations');
      const relList = Array.isArray(data.relationships) ? data.relationships.slice(0, 12) : [];
      let relShown = 0;
      relList.forEach((r) => {
        if (!r || typeof r !== 'object') return;
        const rName = String(r.name || '').trim();
        if (!rName) return;
        const rRel = String(r.relation || '').trim();
        const rNote = String(r.note || '').trim();
        const item = document.createElement('div');
        item.className = 'rel';
        const top = document.createElement('div');
        top.className = 'rel-top';
        const nm = document.createElement('span');
        nm.className = 'rel-name';
        nm.textContent = rName;
        top.appendChild(nm);
        if (rRel) {
          const tag = document.createElement('span');
          tag.className = 'rel-tag';
          tag.textContent = rRel;
          top.appendChild(tag);
        }
        item.appendChild(top);
        if (rNote) {
          const note = document.createElement('div');
          note.className = 'rel-note';
          note.textContent = rNote;
          item.appendChild(note);
        }
        relBox.appendChild(item);
        relShown += 1;
      });
      if (relShown) document.getElementById('sec-relations').style.display = 'block';
    });
  </script>
